import pdfplumber

def classify_pages(path: str, min_chars: int = 50) -> list[str]:
    """Label each page 'text' or 'scan'."""
    labels = []
    with pdfplumber.open(path) as pdf:
        for page in pdf.pages:
            text = page.extract_text() or ""    # None when no text layer
            has_images = len(page.images) > 0   # scans are usually one big image
            if len(text.strip()) >= min_chars:
                labels.append("text")
            elif has_images:
                labels.append("scan")           # send to OCR
            else:
                labels.append("empty")          # blank page, skip
    return labels

print(classify_pages("invoice_0042.pdf"))   # e.g. ['text', 'text']

from datetime import date

def review_reasons(inv, supplier_ids: set[str], line_totals: list[float]) -> list[str]:
    reasons = []
    if inv.total is None or inv.invoice_number is None:
        reasons.append("missing required field")
    if inv.total is not None and abs(sum(line_totals) - inv.total) > 0.01:
        reasons.append("line items do not add up")
    if inv.invoice_date and inv.invoice_date > date.today().isoformat():
        reasons.append("date in the future")
    if inv.supplier_name not in supplier_ids:
        reasons.append("unknown supplier")
    return reasons           # empty list: auto-approve; else human queue

# Accuracy per field on a labelled test set
def field_accuracy(preds: list[dict], gold: list[dict], field: str) -> float:
    hits = sum(p.get(field) == g.get(field) for p, g in zip(preds, gold))
    return hits / len(gold)

